local abc="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local map={};for i=1,#abc do map[abc:sub(i,i)]=i-1 end
local d=table.concat(p)
local out={};local carry,bits=0,0
for i=1,#d do
 local n=map[d:sub(i,i)]
 if n then
  carry=carry*64+n;bits=bits+6
  if bits>=8 then bits=bits-8;out[#out+1]=string.char(math.floor(carry/2^bits));carry=carry%2^bits end
 end
end
local enc=table.concat(out)
local key="NeXLuaMobileV12"
local dec={}
for i=1,#enc do
 local ix=i-1
 local z=bit32 and bit32.bxor(enc:byte(i),key:byte(ix%#key+1),(ix*31+11)%256)
 if not z then
  local a=enc:byte(i);local b=key:byte(ix%#key+1);local c=(ix*31+11)%256
  local function bx(a,b) local n=0;local f=1;while a>0 or b>0 do local u=a%2;local v=b%2;if u~=v then n=n+f end;a=math.floor(a/2);b=math.floor(b/2);f=f*2 end;return n end
  z=bx(bx(a,b),c)
 end
 dec[i]=string.char(z)
end
local run=loadstring or load
assert(type(run)=="function","NeXLua needs loadstring")
local fn,err=run(table.concat(dec));assert(fn,err);return fn()
